def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]

    opp_c = sum(1 for x in opp if x == 'C')
    opp_d = n - opp_c
    my_d = sum(1 for x in my if x == 'D')
    last_my, last_opp = history[-1]

    w = min(8, n)
    recent = opp[n-w:]
    recent_d = sum(1 for x in recent if x == 'D')

    punished = 0
    unpunished = 0
    for i in range(1, n):
        if my[i - 1] == 'D' and opp[i - 1] == 'C':
            if opp[i] == 'D':
                punished += 1
            else:
                unpunished += 1
    evidence = punished + unpunished

    if opp_c == 0:
        return 'D'

    if opp_d * 10 > n * 8:
        return 'D'

    if n >= 10 and recent_d * 8 > w * 7:
        return 'D'

    if last_opp == 'D':
        run_d = 0
        for x in reversed(opp):
            if x == 'D':
                run_d += 1
            else:
                break

        if run_d == 1:
            if n >= 2 and my[-2] == 'D' and opp[-2] == 'C':
                return 'C'
            if last_my == 'D':
                if opp_c * 10 >= n * 7 and recent_d <= 3:
                    return 'C'
                return 'D'
            return 'D'

        if opp_c * 10 >= n * 8 and run_d <= 3 and recent_d <= 5 and rng.random() < 0.2:
            return 'C'
        return 'D'

    if unpunished > 0 and punished == 0:
        if opp_d == 0 and n >= 20:
            return 'D'
        if unpunished >= 2 and opp_c * 10 >= n * 6:
            if rng.random() < 0.8:
                return 'D'
            return 'C'
        if unpunished >= 1 and n >= 60 and opp_c * 10 >= n * 8:
            if rng.random() < 0.4:
                return 'D'
            return 'C'

    if unpunished > punished and unpunished >= 3 and opp_c * 10 >= n * 8:
        if rng.random() < 0.5:
            return 'D'
        return 'C'

    if evidence == 0 and opp_d == 0 and my_d == 0 and last_my == 'C':
        if n == 75 or n == 85:
            return 'D'

    if opp_d == 0 and n >= 98:
        return 'D'

    if opp_c * 10 >= n * 9 and recent_d <= 1 and last_my == 'C':
        if evidence > 0 and unpunished > punished:
            if rng.random() < 0.25:
                return 'D'
            return 'C'
        if rng.random() < 0.02:
            return 'D'
        return 'C'

    if my_d * 10 > n * 4 and opp_c * 10 >= n * 8:
        return 'C'

    return 'C'
